import os, re
root = r"Source/PolyWorld"
matches = []
for dirpath, dirs, files in os.walk(root):
    for f in files:
        if f.endswith(('.h', '.cpp')):
            p = os.path.join(dirpath, f)
            try:
                with open(p, 'r', encoding='utf-8', errors='ignore') as fh:
                    text = fh.read()
            except Exception as e:
                continue
            if 'NetWorth' in text or 'net_worth' in text.lower():
                for i, line in enumerate(text.splitlines()):
                    if 'networth' in line.lower():
                        matches.append((p, i+1, line.strip()))
print(len(matches))
for m in matches[:50]:
    print(m)

